# Modulo value for 998244353
MOD = int(998244353)

# Function to compute binomial coefficient modulo M
def binom_phi(n, r, MOD):
    phi = [0] * r
    phi[0], phi[1] = 1, 1
    for i in range(2, r):
        phi[i] = (MOD - 1) * binom_phi(n-1, i) % MOD
    return phi

# Function to compute Stirling numbers of the second kind modulo M
def stirling(phi, n, r, MOD):
    if r == 0:
        return 1
    if r == 1:
        return phi[0]
    if n == 0:
        return 0
    if n == 1:
        return binom_phi(r, r, MOD)
    if n == r:
        return binom_phi(n, n, MOD) 
    A = stirling(phi, n-1, r-1, MOD)
    B = binom_phi(n, r, MOD)
    C = phi[r-1]
    return ((A + B*C) % MOD - B % MOD + MOD) % MOD

# Function to compute n choose k modulo M using binomial coefficients
def binom_optimized(n, k, MOD):
    if k == 0 or k == n:
        return 1
    temp = binom_phi(n, k, MOD)
    prod = binom_phi(n-k, k, MOD)
    curr = powprod(temp, prod, MOD)
    return powprod(curr, modular_inverse(temp, MOD), MOD)

# Function to compute modular inverse of a number modulo 998244353
def modular_inverse(a, m):
    a = a % m
    for i in range(2, m):
        if (i * i) % m == 1:
            return (a * pow(i, -1, m)) % m

