        stability = max([state & (1 << x) for x in range(n) if walls[x][n+x]] +
                        [state & (1 << x) for x in range(n) if walls[x][n-x]} -
                        [state & (1 << x) for x in range(n) for y in range(n) if walls[x][n+y] and walls[y][x]])
        if stability > best:
            best = stability
