def find_min_energy(N, M, K, transformers):
    # Transform transformers to a directed graph
    transformer_graph = {}
    for x, y, d, t, e in transformers:
        for i in range(1, d + 1):
            nx, ny = x + i * t % d, y - i * t % d
            nx2, ny2 = x + 2 * i * t % d, y + i * t % d
            nx3, ny3 = x, y + t % M
            for nx4, ny4 in [(nx2, ny2), (nx3, ny3)]:
                if 0 <= nx4 < N and 0 <= ny4 < M:
                    if transformer_graph.get((nx4, ny4), None) is None:
                        transformer_graph[(nx4, ny4)] = set()
                    if (x + ((5 * i - 2) % 4) * t % N, y + t % M) not in transformer_graph[(nx4, ny4)]:
                        transformer_graph[(nx4, ny4)].add((x + ((5 * i - 2) % 4) * t % N, y + t % M))

    helper_funcs = {origin: set() for origin in transformer_graph}
    for child in transformer_graph:
        for parent in transformer_graph[child]:
            helper_funcs[parent].add(child)

    # Trace paths to shortest end point
    shortest_paths = {source: (source, 0) for source in helper_funcs}

    for parent in helper_funcs:
        for child in helper_funcs[parent]:
            if (child, helper_funcs[child]) not in helper_funcs:
                helper_funcs[child].add((parent, help_func[child]))
                continue

            if all(child[-1] == trigger and helper_funcs[child][-1][-1] == trigger for trigger in transformer_graph[parent]):
                shortest_paths[child] = list(shortest_paths[parent])[0]
                helper_funcs[child] = shortest_paths[parent].copy()
                break

    # Trace back most energy consumption
    paths = {}
    prev = shortest_paths[transformers[-1][0]]
    for _ in range(max(1, log(len(shortest_paths[transformers[-1][0]]) + 1)) + 2, -1, -1):
        path = paths.setdefault(prev, (None, 0))
        prev = prev[0] if prev[1] % 5 == 0 and path[1] < prev[1] else prev[1]
        helper_funcs[prev].remove(path)

    min_energy = 0
    for destination in shortest_paths[-1]:
        if len(helper_funcs[destination]) == 1 and destination != (0, 0) and destination != (N-1, M-1):
            next_set = next(iter(helper_funcs[destination]))
            if next_set[0] != (0, 0) and next_set[0] != (N-1, M-1):
                min_energy += (N - next_set[0][0]) * (M - next_set[0][1]) + (N - next_set[1][0]) * (M - next_set[1][1])
            break

    return min_energy

