import math

def largest_divisor(N, K):
    if K == 1:
        return 1

    # Use standard deviation formula to get a quick approximation for the largest power of K dividing X
    max_power = 0
    while (max_power * K) ** 2 <= N:
        max_power += 1

    # Calculate X using the arithmetic sequence formula
    X = 1
    for i in range(0, N-1):
        X *= (K + i)

    # Reduce the product X by subtracting off factors of K
    for i in range(1, N-1):
        if X % (K ** i) == 0:
            X = X // (K ** i)
            Y = int(math.ceil(math.log(X, K)))
            max_power -= Y

    # Rewrite X and subtract the largest possible power of K
    X = 1
    for i in range(0, N-1):
        X *= (K + i)

    for i in range(max_power, 0, -1):
        if X % (K ** i) == 0:
            X = X - K ** i
            Y = int(math.ceil(math.log(X, K)))
            max_power -= Y

    # Ensure division by 1000000007 (10^9 + 7)
    mod = 10**9 + 7
    while X < 0:
        X += mod
    while X < 1:
        X += mod

    return X % mod

