class UnionFind:
    def __init__(self, N):
        self.parent = list(range(N))

    def find(self, p):
        if self.parent[p] != p:
            self.parent[p] = self.find(self.parent[p])
        return self.parent[p]

    def union(self, p, q):
        rp, rq = self.find(p), self.find(q)
        if rp == rq:
            return False
        self.parent[rp] = rq
        return True


